BEGIN
  IF x THEN SELECT 1; END IF;
  CASE WHEN a THEN SELECT 2; END CASE;
  l: LOOP LEAVE l; END LOOP;
  WHILE y DO SET y = 0; END WHILE;
  REPEAT SET z = 1; UNTIL z END REPEAT;
